import {Engine,CLASSES,UPGRADES,ABILITIES} from './engine.js';
import {Renderer} from './renderer.js';
import {readSave,persistSave,exportSave,importSave} from './save.js';
import {forge,forgeCost} from './progression.js';
import {executeCommand} from './console.js';
const $=id=>document.getElementById(id);
let {save,storageOK,recovered,writeBlocked,reason:recoveryReason}=readSave();
const slotNames={weapon:'武器',armor:'鎧甲',boots:'戰靴'},icons={knight:'⚔',elf:'➶',mage:'✧'};let selected='knight',game=null,lastStatus='',lastLevel=0,claimed=false,audioOn=false,audioCtx;
const renderer=new Renderer($('world')),keys=new Set(),stick={x:0,y:0};
function writeSave(){const result=persistSave(save);save=result.save;storageOK=result.storageOK;writeBlocked=!!result.writeBlocked;if(!storageOK)toast('儲存空間無法使用；本次傳承只保留至關閉頁面。');}
function campInfo(){$('equipment').textContent=Object.entries(save.equipment).map(([k,v])=>`${slotNames[k]} ${v?'＋'+v:'—'}`).join('　');$('save-note').textContent=storageOK?`本機傳承 · 最長 ${format(save.best)} · 勝利 ${save.wins} 次 · ${save.gold} 金幣`:writeBlocked?'偵測到較新版存檔：此版停止寫入，請先備份':'瀏覽器儲存不可用：關閉頁面將失去進度';}
function classes(){$('classes').replaceChildren(...Object.entries(CLASSES).map(([id,c])=>{const b=document.createElement('button');b.className='class-card'+(id===selected?' selected':'');b.setAttribute('aria-pressed',String(id===selected));b.innerHTML=`<span class="icon">${icons[id]}</span><b>${c.name}</b><small>${c.weapon}<br>${id==='knight'?'近戰・厚甲生存':id==='elf'?'遠程・迅捷貫穿':'法術・範圍爆破'}</small>`;b.onclick=()=>{selected=id;classes();};return b;}));$('profession-note').textContent=`${ABILITIES[selected].name} · ${ABILITIES[selected].description}（空白鍵 / 職業技按鈕）`;}
function toast(text){$('toast').textContent=text;$('toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.opacity=0,2800);}
function sound(freq=440){if(!audioOn)return;try{audioCtx??=new AudioContext();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.setValueAtTime(freq,audioCtx.currentTime);g.gain.setValueAtTime(.025,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.15);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.15);}catch{}}
function start(){game=new Engine(selected,save.equipment,Date.now());claimed=false;lastStatus='';lastLevel=1;keys.clear();resetStick();$('camp').hidden=true;$('footer').hidden=true;$('hud').hidden=false;closeModal();document.body.classList.add('playing');$('class-name').textContent=CLASSES[selected].name+' · '+CLASSES[selected].weapon;toast('自動攻擊已啟動。移動收集翠綠靈魂，留意橘紅敵彈。');sound(220);}
function returnCamp(){game=null;keys.clear();resetStick();$('camp').hidden=false;$('hud').hidden=true;closeModal();$('footer').hidden=false;document.body.classList.remove('playing');campInfo();}
function format(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function action(label,fn,primary=false){const b=document.createElement('button');b.textContent=label;b.className=primary?'primary':'';b.onclick=fn;return b;}
function closeModal(){$('modal').hidden=true;$('camp').inert=false;$('hud').inert=false;document.querySelector('header').inert=false;}
function setModal(kicker,title,description){$('camp').inert=true;$('hud').inert=true;document.querySelector('header').inert=true;$('modal').hidden=false;$('modal-kicker').textContent=kicker;$('modal-title').textContent=title;$('modal-description').textContent=description;$('modal-content').replaceChildren();$('modal-actions').replaceChildren();keys.clear();resetStick();}
function syncStatus(){if(!game||game.status===lastStatus&&game.level===lastLevel)return;lastStatus=game.status;lastLevel=game.level;if(game.status==='playing'){closeModal();return;}if(game.status==='upgrade'){setModal('SOUL AWAKENING · LV '+game.level,'靈魂覺醒','時間已停止。選擇一項祝福，改變這場遠征。');const div=document.createElement('div');div.className='upgrade-options';game.choices.forEach(c=>{const b=document.createElement('button');b.innerHTML=`<strong>${c.name} <small>第 ${c.level} 階${c.level===5?' · 進化':''}</small></strong><small>${c.description}</small>`;b.onclick=()=>{if(game.chooseUpgrade(c.id)){sound(620);lastStatus='';syncStatus();}};div.append(b);});$('modal-content').append(div);sound(550);}
 else if(game.status==='paused'){setModal('A MOMENT OF SILENCE','暫歇，為了走得更遠','WASD / 方向鍵移動，空白鍵職業技，Q 治療，Esc 繼續。返回營地將放棄本次未結算戰利品。');$('modal-actions').append(action('繼續遠征',()=>{game.togglePause();syncStatus();},true),action('返回營地',returnCamp));addDiagnostics();}
 else if(['dead','victory'].includes(game.status)){const won=game.status==='victory';if(!claimed){claimed=true;save.gold+=game.rewards.gold;save.equipment={...game.rewards.equipment};save.best=Math.max(save.best,game.time);if(won)save.wins++;writeSave();}setModal(won?'DAWN HAS COME':'THE FOREST REMEMBERS',won?'黎明，屬於倖存者。':'此刻倒下，傳承不滅。',won?'你擊倒了暮林君王，守住了最後一道曙光。':'帶著經驗與戰利品，準備下一場遠征。');$('modal-content').innerHTML=`<div class="stats"><span><b>${format(game.time)}</b>生存時間</span><span><b>${game.kills}</b>擊倒魔物</span><span><b>${game.rewards.gold}</b>獲得金幣</span></div><p>${game.rewards.drop?`取得 ${slotNames[game.rewards.drop.slot]} ＋${game.rewards.drop.tier} · 較強裝備已保留`:'擊倒 35 隻魔物可獲得傳承裝備'}</p><div class="damage-row"><span>傷害來源</span><span>有效傷害</span></div>`;for(const [k,v]of Object.entries(game.damage)){const r=document.createElement('div');r.className='damage-row';r.innerHTML=`<span>${k==='weapon'?CLASSES[selected].weapon:k==='ability'?ABILITIES[selected].name:UPGRADES[k].name}</span><span>${Math.round(v).toLocaleString()}</span>`;$('modal-content').append(r);}$('modal-actions').append(action('再次遠征',start,true),action('返回營地',returnCamp));sound(won?660:140);}
 const focus=$('modal-actions').querySelector('button')||modalFocusables()[0];focus?.focus({preventScroll:true});}
function hud(){if(!game)return;const p=game.player;$('ability-name').textContent=ABILITIES[selected].name;$('ability-cooldown').textContent=game.abilityCooldown>0?Math.ceil(game.abilityCooldown)+'s':'就緒';$('ability').disabled=game.status!=='playing'||game.abilityCooldown>0;$('health').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;$('hp-fill').style.width=`${p.hp/p.maxHp*100}%`;$('xp-fill').style.width=`${game.xp/game.xpNext*100}%`;$('timer').textContent=format(game.time);$('level').textContent=`等級 ${game.level}`;$('kills').textContent=`擊倒 ${game.kills}`;$('wave').textContent=game.bossDefeated?'君王已倒下':game.time>=420?'君王降臨':`魔潮 ${Math.floor(game.time/60)+1}`;$('potions').textContent=game.potions;$('heal').disabled=game.status!=='playing'||game.potions===0||p.hp>=p.maxHp;const boss=game.enemies.find(e=>e.type==='boss');$('boss').hidden=!boss;if(boss)$('boss-fill').style.width=`${Math.max(0,boss.hp/boss.maxHp)*100}%`;$('skills').innerHTML=['weapon','orb','lightning'].filter(k=>k==='weapon'||game.upgrades[k]).map(k=>`<span>${k==='weapon'?CLASSES[selected].weapon:k==='ability'?ABILITIES[selected].name:UPGRADES[k].name} ${game.upgrades[k]>=5?'✦ 進化':`＋${game.upgrades[k]}`}</span>`).join('');}
$('start').onclick=start;$('forge').onclick=showForge;$('backup').onclick=showBackup;$('ability').onclick=useAbility;$('touch').onclick=()=>{const enabled=document.body.classList.toggle('touch-controls');$('touch').textContent=enabled?'觸控：開':'觸控：自動';$('touch').setAttribute('aria-pressed',String(enabled));};$('pause').onclick=()=>{game?.togglePause();syncStatus();};$('heal').onclick=()=>{if(game?.heal())sound(700);};$('sound').onclick=()=>{audioOn=!audioOn;$('sound').textContent='音效：'+(audioOn?'開':'關');sound();};
function modalFocusables(){return [...$('modal').querySelectorAll('button:not([disabled]),input,textarea,select,summary')].filter(el=>el.getClientRects().length>0);}
window.addEventListener('keydown',e=>{
 const k=e.key.toLowerCase();
 if(k==='tab'&&!$('modal').hidden){const targets=modalFocusables(),first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}
 if(k==='escape'){if(e.repeat)return;e.preventDefault();if(game){game.togglePause();syncStatus();}else closeModal();return;}
 if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;
 if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)&&game)e.preventDefault();
 if(e.repeat)return;if(k==='q'&&game?.heal())sound(700);if(k===' ')useAbility();keys.add(k);
});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function autoPause(){keys.clear();resetStick();if(game?.status==='playing'){game.togglePause();syncStatus();}}window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{if(document.hidden)autoPause();});
const joystick=$('joystick');let pointer=null;function resetStick(){stick.x=stick.y=0;pointer=null;joystick.firstElementChild.style.transform='translate(0,0)';}function moveStick(e){if(pointer!==e.pointerId)return;const r=joystick.getBoundingClientRect();let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,n=Math.max(1,Math.hypot(x,y)/38);x/=n;y/=n;stick.x=x/38;stick.y=y/38;joystick.firstElementChild.style.transform=`translate(${x}px,${y}px)`;}joystick.onpointerdown=e=>{if(game?.status!=='playing')return;pointer=e.pointerId;joystick.setPointerCapture(pointer);moveStick(e);};joystick.onpointermove=moveStick;joystick.onpointerup=resetStick;joystick.onpointercancel=resetStick;joystick.onlostpointercapture=resetStick;
let last=performance.now(),ui=0;function frame(now){let dt=Math.min(.05,(now-last)/1000);last=now;if(game){game.update(dt,inputVector());syncStatus();ui+=dt;if(ui>.1){hud();ui=0;}}renderer.render(game,game?.time??now/1000);requestAnimationFrame(frame);}classes();campInfo();if(recovered)toast(recoveryReason==='backup'?'已從備份復原傳承。建議匯出一份安全備份。':'存檔無法讀取且沒有有效備份；已開啟新傳承。');requestAnimationFrame(frame);
function inputVector(){return {x:stick.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y:stick.y+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)};}
function useAbility(){if(game?.useAbility(inputVector())){sound(360);toast(ABILITIES[selected].name);}}
function showForge(){setModal('LEGACY FORGE','把戰利品，鍛成下一次勝算。',`持有 ${save.gold} 金幣。每次提升一階，最高 ＋5；掉落不會降低已鍛造裝備。`);const grid=document.createElement('div');grid.className='forge-grid';for(const slot of ['weapon','armor','boots']){const tier=save.equipment[slot],cost=forgeCost(save,slot);const card=document.createElement('section');card.innerHTML=`<h3>${slotNames[slot]} ＋${tier}</h3><p>${slot==='weapon'?'每階傷害 ＋8%':slot==='armor'?'每階生命 ＋10、減傷 ＋1':'每階移速 ＋5'}</p>`;const b=action(tier>=5?'已達最高階':`鍛造 ＋${tier+1} · ${cost} 金`,()=>{const result=forge(save,slot);if(!result.ok){toast(result.message);return;}save=result.save;writeSave();campInfo();showForge();toast(result.message);});b.disabled=tier>=5||save.gold<cost||writeBlocked;card.append(b);grid.append(card);}$('modal-content').append(grid);$('modal-actions').append(action('返回營地',()=>{closeModal();$('forge').focus();}));$('modal-actions').querySelector('button').focus();}
function showBackup(){setModal('KEEP YOUR LEGACY','傳承備份','複製備份碼保存在安全位置；匯入會取代目前傳承。只處理本機資料，不會上傳。');const label=document.createElement('label');label.textContent='傳承備份碼';label.htmlFor='save-code';const area=document.createElement('textarea');area.id='save-code';area.rows=7;area.spellcheck=false;area.value=exportSave(save);const status=document.createElement('p');status.setAttribute('role','status');$('modal-content').append(label,area,status);$('modal-actions').append(action('選取備份碼',()=>{area.focus();area.select();}),action('檢查匯入',()=>{const result=importSave(area.value);if(!result.ok){status.textContent=result.message;return;}setModal('CONFIRM IMPORT','取代本機傳承？',`即將匯入 ${result.save.gold} 金幣、最高 ${format(result.save.best)}。目前資料將由備份保留，但建議先自行複製。`);$('modal-actions').append(action('確認取代',()=>{if(writeBlocked){toast('較新版存檔受到保護，未覆寫。');return;}save=result.save;writeSave();campInfo();closeModal();toast(storageOK?'傳承已匯入。':'已載入記憶體；儲存不可用，請保留備份碼。');},true),action('取消',showBackup));$('modal-actions').lastElementChild.focus();}),action('關閉',()=>closeModal()));area.focus();}
function addDiagnostics(){const details=document.createElement('details');details.className='diagnostics';const summary=document.createElement('summary');summary.textContent='遠征情報 · 唯讀指令';const form=document.createElement('form');const input=document.createElement('input');input.placeholder='help / status / player / skills';input.setAttribute('aria-label','遠征情報指令');input.maxLength=80;const output=document.createElement('output');output.setAttribute('aria-live','polite');const button=document.createElement('button');button.type='submit';button.textContent='查詢';form.append(input,button);form.onsubmit=e=>{e.preventDefault();output.textContent=executeCommand(input.value,game).message;};details.append(summary,form,output);$('modal-content').append(details);}
